# SecondSite closed-loop harness A/B (Kaggle 4x L4, internet off). Generated by build_kernel.py; do not edit the output.
# Arm A = team control nb5 (as in nb5_ctrl_full) + a fixed seed; Arm B = the same + the `second_site` ADK skill and a
# 4-line prompt section. Both arms run AT THE SAME TIME against ONE vLLM server (same tasks, same order, same
# concurrency), so GPU contention is shared. Built on the team runner _upload_l4_batch1/kaggle/eval/run_template.py.
# AB_DRY_RUN=1: CPU dry run (no install, no GPU, no swegemma): payload, YAML, skill, script and result parsing only.
import asyncio, base64, collections, glob, io, json, math, os, pathlib, re, shutil, statistics, subprocess, sys, tarfile, tempfile, time

PAYLOAD_TGZ = base64.b64decode("")
T0 = time.time()
DRY = os.environ.get("AB_DRY_RUN") == "1"
INPUT_ROOT = os.environ.get("AB_INPUT_ROOT", "/kaggle/input")
WORK = pathlib.Path(os.environ.get("AB_WORK", "/kaggle/working"))
WORK.mkdir(parents=True, exist_ok=True)
LOG = open(WORK / "run.log", "a", buffering=1, encoding="utf-8")


def log(*a):
    s = time.strftime("%H:%M:%S ") + f"[{(time.time() - T0) / 60:5.1f}m] " + " ".join(str(x) for x in a)
    print(s, flush=True)
    LOG.write(s + "\n")


def sh(cmd, timeout=None, check=False):
    log("$", cmd[:300])
    r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=timeout)
    out = (r.stdout[-3000:] + ("\n" + r.stderr[-3000:] if r.stderr.strip() else "")).strip()
    if out:
        log(out)
    if check and r.returncode != 0:
        raise SystemExit(f"command failed rc={r.returncode}: {cmd[:120]}")
    return r


def first(pattern):
    hits = sorted(glob.glob(pattern, recursive=True))
    return hits[0] if hits else None


# ---------------------------------------------------------------- 0. payload (bundles, gold sites, config)
PAY = pathlib.Path(os.environ.get("AB_PAYLOAD_DIR", "/tmp/ab_payload"))
if PAY.exists():
    shutil.rmtree(PAY)
PAY.mkdir(parents=True)
with tarfile.open(fileobj=io.BytesIO(PAYLOAD_TGZ), mode="r:gz") as tf:
    tf.extractall(PAY)
CFG = json.loads((PAY / "ab_config.json").read_text(encoding="utf-8"))
GOLD = json.loads((PAY / "gold_sites.json").read_text(encoding="utf-8"))
BUNDLE_ROOT = PAY / "bundles"
ARMS = CFG["arms"]  # [{"name": "A_ctrl", "bundle": "nb5_ctrl"}, {"name": "B_second_site", "bundle": "nb5_ss"}]
HARD_S = 60 * float(CFG["hard_deadline_min"])  # from script start: stop and summarise
SOFT_S = HARD_S - 60 * float(CFG["soft_margin_min"])  # no task starts after this
OUT_JSONL = WORK / "ab_task_results.jsonl"
OUT_SUMMARY = WORK / "ab_summary.json"
STATE = {"status": "starting", "skipped": collections.defaultdict(list), "errors": [], "preflight": {}}
log("CFG", json.dumps({k: v for k, v in CFG.items() if k != "task_ids"}), "| tasks", len(CFG["task_ids"]))

# ---------------------------------------------------------------- result parsing (pure, also used by the dry run)
HUNK_RE = re.compile(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@")
DEF_RE = re.compile(r"^\s*(?:async\s+)?def\s+([A-Za-z_]\w*)|^\s*class\s+([A-Za-z_]\w*)")
LIST_RE = re.compile(r"^\s*\d+\.\s+(\S+?):(\d+)-(\d+)\s+(\S+)")


def patch_touch(patch):
    """agent patch -> {path: {"old": set(old-side changed lines), "ins": set(old line an insertion lands before),
    "added_defs": set(def/class names on '+' lines)}}."""
    out, path, in_hunk, o = {}, None, False, 0
    for line in (patch or "").splitlines():
        if line.startswith("diff --git "):
            m = re.match(r"diff --git a/(.*) b/(.*)$", line)
            path, in_hunk = (m.group(2) if m else None), False
            continue
        if not in_hunk and line.startswith("+++ "):
            q = line[4:].strip()
            path = None if q == "/dev/null" else re.sub(r"^b/", "", q)
            continue
        if not in_hunk and line.startswith("--- "):
            continue
        m = HUNK_RE.match(line)
        if m:
            in_hunk = True
            o = int(m.group(1)) + (1 if (m.group(2) or "1") == "0" else 0)
            continue
        if not in_hunk or path is None:
            continue
        d = out.setdefault(path, {"old": set(), "ins": set(), "added_defs": set()})
        tag, body = line[:1], line[1:]
        if tag == "-":
            if body.strip():
                d["old"].add(o)
            o += 1
        elif tag == "+":
            if body.strip():
                d["ins"].add(o)
                mm = DEF_RE.match(body)
                if mm:
                    d["added_defs"].add(mm.group(1) or mm.group(2))
        elif tag == " ":
            o += 1
    return out


def gold_edited(patch, gold):
    """Which gold sites (base spans from the gold patch) the agent patch touches."""
    t = patch_touch(patch)
    hit = []
    for g in gold:
        d = t.get(g["path"])
        if not d:
            continue
        if g["added"] or g["start"] is None:
            if g["qual"].split(".")[-1] in d["added_defs"]:
                hit.append(g["id"])
            continue
        s, e = g["start"], g["end"]
        if any(s <= x <= e for x in d["old"]) or any(s < x <= e for x in d["ins"]):
            hit.append(g["id"])
    return hit


def parse_trace(path):
    """Tool-call counts and the second-site check's delivery from a swegemma SessionTrace JSON."""
    info = {"trace_found": False, "tool_counts": {}, "ss_called": False, "ss_ok": False, "ss_listed": [], "ss_n_calls": 0,
            "ss_error": None, "ss_call_index": None, "first_edit_index": None, "submit_index": None, "edits_after_ss": 0}
    try:
        d = json.load(open(path, encoding="utf-8"))
    except Exception:
        return info
    info["trace_found"] = True
    cnt, idx = collections.Counter(), 0
    for s in d.get("steps", []) or []:
        for tc in s.get("tool_calls") or []:
            nm = tc.get("function_name") or tc.get("name") or "?"
            args = tc.get("arguments") or {}
            cnt[nm] += 1
            idx += 1
            obs = json.dumps(s.get("observation") or "")
            is_edit = nm in ("edit_file", "write_file") or (nm == "run_command" and re.search(
                r"sed -i|\.write_text\(|open\([^)]*['\"]w|str\.replace|>\s*\S+\.py", json.dumps(args)))
            if is_edit and info["first_edit_index"] is None and '\\"status\\": \\"ok' in obs:
                info["first_edit_index"] = idx
            if is_edit and info["ss_call_index"] is not None:
                info["edits_after_ss"] += 1
            if nm == "submit_patch" and info["submit_index"] is None:
                info["submit_index"] = idx
            if nm == "run_skill_script" and ("second_site" in json.dumps(args) or "second-site" in json.dumps(args)):
                info["ss_called"], info["ss_n_calls"] = True, info["ss_n_calls"] + 1
                try:
                    content = json.loads((s.get("observation") or {}).get("content") or "{}")
                except Exception:
                    content = {}
                stdout = content.get("stdout", "") if isinstance(content, dict) else ""
                if "second_site: edited so far" in stdout:
                    if not info["ss_ok"]:
                        info["ss_call_index"] = idx
                    info["ss_ok"] = True
                    info["ss_listed"] = [f"{m.group(1)}::{m.group(4)}" for m in map(LIST_RE.match, stdout.splitlines()) if m]
                elif info["ss_error"] is None:
                    info["ss_error"] = (content.get("error_code") or content.get("error") or stdout or obs)[:200] \
                        if isinstance(content, dict) else obs[:200]
    info["tool_counts"] = dict(cnt)
    return info


def make_row(arm, tid, res, wall_s, results_dir):
    gold = GOLD.get(tid, {}).get("gold", [])
    patch = res.get("agent_patch") or ""
    edited = gold_edited(patch, gold)
    tr = parse_trace(pathlib.Path(results_dir) / "traces" / f"trace_{tid}.json")
    missed = [g["id"] for g in gold if g["id"] not in edited]
    return {
        "arm": arm, "task_id": tid, "resolved": bool(res.get("resolved")), "patch": patch,
        "gold_edited": len(edited), "gold_total": len(gold), "gold_edited_ids": edited,
        "second_site_ran": tr["ss_ok"], "second_site_called": tr["ss_called"], "second_site_n_calls": tr["ss_n_calls"],
        "second_site_error": tr["ss_error"], "second_site_listed": tr["ss_listed"],
        "second_site_listed_missed_gold": [h for h in tr["ss_listed"] if h in missed or h in edited],
        "edits_after_second_site": tr["edits_after_ss"], "first_edit_call": tr["first_edit_index"],
        "second_site_call": tr["ss_call_index"], "submit_call": tr["submit_index"],
        "tool_calls": res.get("tool_calls"), "tool_counts": tr["tool_counts"], "llm_calls": res.get("total_llm_calls"),
        "seconds": res.get("duration_seconds"), "wall_seconds": round(wall_s, 1), "error": res.get("error"),
        "test_exit_code": res.get("test_exit_code"), "trace_found": tr["trace_found"],
        "t_finished_min": round((time.time() - T0) / 60, 1),
    }


def mcnemar_exact(b, c):
    n = b + c
    if n == 0:
        return 1.0
    k = min(b, c)
    return min(1.0, 2.0 * sum(math.comb(n, i) for i in range(k + 1)) / 2 ** n)


def summarize(rows, status):
    by = collections.defaultdict(dict)
    for r in rows:
        by[r["arm"]][r["task_id"]] = r
    names = [a["name"] for a in ARMS]
    out = {"status": status, "elapsed_min": round((time.time() - T0) / 60, 1), "arms": {}, "config": {
        k: v for k, v in CFG.items() if k != "task_ids"}, "n_tasks_planned": len(CFG["task_ids"]),
        "skipped_by_time_guard": {k: v for k, v in STATE["skipped"].items()}, "errors": STATE["errors"][-20:],
        "preflight": STATE["preflight"]}
    for a in names:
        rs = list(by[a].values())
        med = lambda xs: statistics.median(xs) if xs else None  # noqa: E731
        out["arms"][a] = {
            "n_done": len(rs), "resolved": sum(r["resolved"] for r in rs),
            "resolve_rate": round(sum(r["resolved"] for r in rs) / len(rs), 4) if rs else None,
            "all_gold_edited": sum(1 for r in rs if r["gold_total"] and r["gold_edited"] == r["gold_total"]),
            "mean_gold_coverage": round(statistics.mean(r["gold_edited"] / r["gold_total"] for r in rs if r["gold_total"]), 4) if rs else None,
            "empty_patch": sum(1 for r in rs if not r["patch"]),
            "second_site_ran": sum(r["second_site_ran"] for r in rs), "second_site_called": sum(r["second_site_called"] for r in rs),
            "listed_a_missed_or_edited_gold": sum(1 for r in rs if r["second_site_listed_missed_gold"]),
            "median_tool_calls": med([r["tool_calls"] for r in rs if r["tool_calls"] is not None]),
            "median_seconds": med([r["seconds"] for r in rs if r["seconds"] is not None]),
            "errors": sum(1 for r in rs if r["error"]),
        }
    split = CFG.get("task_status", {})
    for a in names:  # the team's gold/empty runs: only `clean` tasks can flip; `broken` = gold patch fails here
        bs = collections.defaultdict(lambda: {"n_done": 0, "resolved": 0, "all_gold_edited": 0})
        for r in by[a].values():
            d = bs[split.get(r["task_id"], "unknown")]
            d["n_done"] += 1
            d["resolved"] += int(r["resolved"])
            d["all_gold_edited"] += int(bool(r["gold_total"]) and r["gold_edited"] == r["gold_total"])
        out["arms"][a]["by_task_status"] = dict(bs)
    if len(names) == 2:
        A, B = names
        common = sorted(set(by[A]) & set(by[B]))
        clean = [t for t in common if split.get(t) == "clean"]
        bc = [t for t in clean if by[A][t]["resolved"] and not by[B][t]["resolved"]]
        cc = [t for t in clean if by[B][t]["resolved"] and not by[A][t]["resolved"]]
        out["paired_clean"] = {"n_common_clean": len(clean), f"resolved_{A}": sum(by[A][t]["resolved"] for t in clean),
                               f"resolved_{B}": sum(by[B][t]["resolved"] for t in clean), f"only_{A}": bc, f"only_{B}": cc,
                               "mcnemar_exact_p": round(mcnemar_exact(len(bc), len(cc)), 4)}
        b = [t for t in common if by[A][t]["resolved"] and not by[B][t]["resolved"]]
        c = [t for t in common if by[B][t]["resolved"] and not by[A][t]["resolved"]]
        both = sum(1 for t in common if by[A][t]["resolved"] and by[B][t]["resolved"])
        cov_a = sum(1 for t in common if by[A][t]["gold_total"] and by[A][t]["gold_edited"] == by[A][t]["gold_total"])
        cov_b = sum(1 for t in common if by[B][t]["gold_total"] and by[B][t]["gold_edited"] == by[B][t]["gold_total"])
        ran = [t for t in common if by[B][t]["second_site_ran"]]
        out["paired"] = {
            "n_common": len(common), f"resolved_{A}": both + len(b), f"resolved_{B}": both + len(c), "both": both,
            f"only_{A}": b, f"only_{B}": c, "mcnemar_exact_p": round(mcnemar_exact(len(b), len(c)), 4),
            f"all_gold_edited_{A}": cov_a, f"all_gold_edited_{B}": cov_b,
            "B_tasks_where_check_ran": len(ran),
            "on_check_ran_tasks": {f"resolved_{A}": sum(by[A][t]["resolved"] for t in ran),
                                   f"resolved_{B}": sum(by[B][t]["resolved"] for t in ran)},
            "note": "exploratory: one paired run per arm; team rerun noise on 71 tasks is 4-7 solves",
        }
    return out


ROWS = []


def persist(status):
    tmp = OUT_JSONL.with_suffix(".tmp")
    with open(tmp, "w", encoding="utf-8") as f:
        for r in ROWS:
            f.write(json.dumps(r) + "\n")
    os.replace(tmp, OUT_JSONL)
    s = summarize(ROWS, status)
    tmp = OUT_SUMMARY.with_suffix(".tmp")
    tmp.write_text(json.dumps(s, indent=1), encoding="utf-8")
    os.replace(tmp, OUT_SUMMARY)
    return s


# ---------------------------------------------------------------- preflight checks that need no GPU
def check_bundles():
    import yaml

    class L(yaml.SafeLoader):
        pass
    L.add_constructor("!include", lambda loader, node: ("!include", loader.construct_scalar(node)))
    rep = {}
    for arm in ARMS:
        d = BUNDLE_ROOT / arm["bundle"]
        ag = yaml.load((d / "agent.yaml").read_text(encoding="utf-8"), Loader=L)
        ev = yaml.safe_load((d / "eval_config.yaml").read_text(encoding="utf-8"))
        sp = yaml.safe_load((d / "configs" / "sampling.yaml").read_text(encoding="utf-8"))
        for inc in (ag["instruction"], ag["generate_content_config"]):
            assert inc[0] == "!include" and (d / inc[1]).is_file(), inc
        for sk in ag.get("skills") or []:
            md = (d / sk / "SKILL.md").read_text(encoding="utf-8")
            fm = yaml.safe_load(md.split("---")[1])
            assert fm["name"] == pathlib.Path(sk).name, fm
            # ADK 1.36 SkillFrontmatter: lowercase kebab-case, at most 64 chars, description at most 1024 chars
            assert re.fullmatch(r"[a-z0-9]+(-[a-z0-9]+)*", fm["name"]) and len(fm["name"]) <= 64, fm["name"]
            assert 0 < len(fm.get("description") or "") <= 1024, "SKILL.md description"
            for py in (d / sk / "scripts").glob("*.py"):
                compile(py.read_text(encoding="utf-8"), str(py), "exec")
        exts = {p.suffix for p in d.rglob("*") if p.is_file()}
        assert exts <= {".yaml", ".yml", ".md", ".txt", ".py", ".json", ".safetensors"}, exts
        rep[arm["name"]] = {"bundle": arm["bundle"], "skills": ag.get("skills") or [], "tools": ag["tools"],
                            "eval": ev["evaluation"], "sampling": sp,
                            "prompt_lines": len((d / "prompts" / "system.md").read_text(encoding="utf-8").splitlines())}
    a, b = (BUNDLE_ROOT / ARMS[0]["bundle"]), (BUNDLE_ROOT / ARMS[1]["bundle"])
    for rel in ("eval_config.yaml", "configs/sampling.yaml"):
        assert (a / rel).read_bytes() == (b / rel).read_bytes(), f"{rel} differs between arms"
    rep["prompt_lines_added_in_B"] = rep[ARMS[1]["name"]]["prompt_lines"] - rep[ARMS[0]["name"]]["prompt_lines"]
    return rep


def check_second_site_git():
    """Run the bundle's second_site.py against a throwaway git repo with the system git, the way the sandbox
    will: cwd elsewhere, the workspace given only through PYTHONPATH."""
    if not shutil.which("git"):
        return {"ok": None, "why": "no git on PATH (local dry run)"}
    script = BUNDLE_ROOT / ARMS[1]["bundle"] / "skills" / "second-site" / "scripts" / "second_site.py"
    ws = pathlib.Path(tempfile.mkdtemp(prefix="ss_git_"))
    (ws / "pkg").mkdir()
    (ws / "pkg" / "__init__.py").write_text("")
    (ws / "pkg" / "a.py").write_text("class Route:\n    def get(self, x):\n        return x\n\n    def put(self, x):\n        return x\n\n"
                                     "def helper(y):\n    return y\n")
    (ws / "pkg" / "b.py").write_text("def get(z):\n    return z\n")
    env = dict(os.environ, GIT_AUTHOR_NAME="t", GIT_AUTHOR_EMAIL="t@t", GIT_COMMITTER_NAME="t", GIT_COMMITTER_EMAIL="t@t")
    for c in ("git init -q", "git add -A", "git commit -qm base"):
        subprocess.run(c, shell=True, cwd=ws, env=env, check=True)
    (ws / "pkg" / "a.py").write_text((ws / "pkg" / "a.py").read_text().replace("return x\n\n    def put", "return x + 1\n\n    def put", 1))
    subprocess.run("git commit -qam second", shell=True, cwd=ws, env=env, check=True)
    (ws / "pkg" / "a.py").write_text((ws / "pkg" / "a.py").read_text().replace("return x + 1", "return x + 2", 1))
    r = subprocess.run([sys.executable, str(script)], cwd=tempfile.gettempdir(), capture_output=True, text=True, timeout=60,
                       env=dict(os.environ, PYTHONPATH=str(ws)))
    out = r.stdout
    ok = "edited so far: pkg/a.py::Route.get" in out and "Route.put" in out and len(out) <= 1500
    shutil.rmtree(ws, ignore_errors=True)
    return {"ok": ok, "stdout": out[:900], "stderr": r.stderr[-300:]}


def mock_dry_run():
    """Local CPU dry run: fake TaskResults + fake traces through make_row/summarize/persist."""
    tids = CFG["task_ids"][:4]
    tmpres = WORK / "mock_results"
    for arm in ARMS:
        (tmpres / arm["name"] / "traces").mkdir(parents=True, exist_ok=True)
    full_gold = {t: GOLD[t]["gold"] for t in tids}
    for i, t in enumerate(tids):
        g = full_gold[t]
        g0 = next((x for x in g if not x["added"]), None)
        one = f"diff --git a/{g0['path']} b/{g0['path']}\n--- a/{g0['path']}\n+++ b/{g0['path']}\n@@ -{g0['start']},1 +{g0['start']},1 @@\n-x\n+y\n" if g0 else ""
        both = one
        for x in g[1:]:
            if not x["added"]:
                both += f"diff --git a/{x['path']} b/{x['path']}\n--- a/{x['path']}\n+++ b/{x['path']}\n@@ -{x['end']},1 +{x['end']},1 @@\n-x\n+y\n"
        listed = "\n".join(f"{k + 1}. {x['path']}:{x['start'] or 1}-{x['end'] or 1} {x['qual']} | same file" for k, x in enumerate(g[1:4]))
        ss_obs = {"content": json.dumps({"skill_name": "second-site", "file_path": "scripts/second_site.py", "status": "success",
                                         "stdout": "second_site: edited so far: " + (g0["id"] if g0 else "?") + "\nOther ...\n" + listed})}
        nf_obs = {"content": json.dumps({"error": "Script 'second_site' not found in skill 'second-site'.", "error_code": "SCRIPT_NOT_FOUND"})}
        ok_edit = {"content": "{\"status\": \"ok\", \"filepath\": \"x.py\"}"}
        for arm in ARMS:
            steps = [{"tool_calls": [{"function_name": "run_command", "arguments": {"command": "git grep -n foo"}}], "observation": {"content": "{}"}},
                     {"tool_calls": [{"function_name": "edit_file", "arguments": {"filepath": "x.py"}}], "observation": ok_edit}]
            if arm["name"] == ARMS[1]["name"] and i != 3:
                steps.append({"tool_calls": [{"function_name": "run_skill_script", "arguments": {"skill_name": "second-site", "file_path": "scripts/second_site.py" if i != 2 else "second_site", "args": {}}}],
                              "observation": ss_obs if i != 2 else nf_obs})
                steps.append({"tool_calls": [{"function_name": "edit_file", "arguments": {"filepath": "y.py"}}], "observation": ok_edit})
            steps.append({"tool_calls": [{"function_name": "submit_patch", "arguments": {}}], "observation": {"content": "{\"status\": \"ok\"}"}})
            (tmpres / arm["name"] / "traces" / f"trace_{t}.json").write_text(json.dumps({"steps": steps}))
            patch = (both if arm["name"] == ARMS[1]["name"] else one) if i != 1 else ""
            res = {"resolved": arm["name"] == ARMS[1]["name"] and i == 0, "agent_patch": patch, "tool_calls": 20 + i,
                   "total_llm_calls": 25, "duration_seconds": 200.0 + i, "error": None if patch else "empty patch", "test_exit_code": 1}
            ROWS.append(make_row(arm["name"], t, res, 210.0, tmpres / arm["name"]))
            persist("dry_run")
    s = persist("dry_run_done")
    rows = [json.loads(l) for l in open(OUT_JSONL, encoding="utf-8")]
    req = {"arm", "task_id", "resolved", "patch", "gold_edited", "gold_total", "second_site_ran", "tool_calls", "seconds"}
    assert all(req <= set(r) for r in rows), "missing fields"
    rb = [r for r in rows if r["arm"] == ARMS[1]["name"]]
    ra = [r for r in rows if r["arm"] == ARMS[0]["name"]]
    assert [r["second_site_ran"] for r in rb] == [True, True, False, False], [r["second_site_ran"] for r in rb]
    assert rb[2]["second_site_error"] == "SCRIPT_NOT_FOUND" and not any(r["second_site_ran"] for r in ra)
    assert rb[0]["gold_edited"] == sum(1 for x in full_gold[tids[0]] if not x["added"]), (rb[0]["gold_edited"], full_gold[tids[0]])
    assert ra[0]["gold_edited"] == 1 and rb[1]["gold_edited"] == 0
    assert s["paired"]["n_common"] == 4 and s["paired"]["only_" + ARMS[1]["name"]] == [tids[0]]
    log("DRY_RUN mock rows OK:", len(rows), "| paired:", json.dumps(s["paired"])[:600])
    return s


