log("python", sys.version.split()[0], "| dry" if DRY else "| kaggle")
STATE["preflight"]["bundles"] = check_bundles()
log("PREFLIGHT bundles:", json.dumps(STATE["preflight"]["bundles"])[:1500])
STATE["preflight"]["second_site_git"] = check_second_site_git()
log("PREFLIGHT second_site git CLI:", json.dumps(STATE["preflight"]["second_site_git"])[:1200])
