# ---------------------------------------------------------------- 3. compile both bundles on CPU before booting vLLM
import torch  # noqa: E402
import yaml  # noqa: E402
from adk_submission import VllmConfig, VllmServer, compile_submission, discover_adapters  # noqa: E402
from swegemma.config import ALLOWED_ADAPTER_EXTENSIONS, EvalConfig, build_submission_limits  # noqa: E402

model_cfg = [p for p in glob.glob(INPUT_ROOT + "/**/config.json", recursive=True) if "w4a16" in p.lower()]
model_cfg = [p for p in model_cfg if "31b" in p.lower()] or model_cfg
assert model_cfg, "31B W4A16 model not attached"
MODEL_DIR = str(pathlib.Path(sorted(model_cfg)[0]).parent)
PORT = 8000


def make_server(bundle):  # team runner make_server(), same flags as the scorer recipe
    return VllmServer(VllmConfig(
        model=MODEL_DIR, port=PORT, host="127.0.0.1", tool_call_parser="gemma4", reasoning_parser="gemma4",
        max_model_len=32768, dtype="bfloat16" if torch.cuda.is_bf16_supported() else "auto", gpu_memory_utilization=0.90,
        enable_auto_tool_choice=True, enable_lora=True, max_loras=8, max_lora_rank=128, tensor_parallel_size=4,
        startup_timeout=60 * 20, extra_args=[]),
        adapter_manifest=discover_adapters(str(BUNDLE_ROOT / bundle), adapter_extensions=ALLOWED_ADAPTER_EXTENSIONS))


server = make_server(ARMS[0]["bundle"])
try:
    from swegemma.models.discovery import validate_single_declared_model  # swegemma <= 0.2.7
except ImportError:
    from adk_submission import discover_declared_models

    def validate_single_declared_model(sub):
        declared = sorted(discover_declared_models(sub))
        assert len(declared) == 1, f"{sub}: expected one declared model, got {declared}"
        return declared[0]
ALIASES = ["gemma-4-31b-it-qat-w4a16-ct", "gemma-4-31b-it", "gemma-4-31b"]


def registry_for(sub):
    declared = validate_single_declared_model(sub)
    return server.create_model_registry(aliases=[declared, *ALIASES], model_prefix="openai/", api_key="EMPTY")


def flat_tool_names(tools, out=None, depth=0):
    out = [] if out is None else out
    for item in (tools or []) if depth < 6 else []:
        nm = getattr(item, "name", None)
        if isinstance(nm, str) and nm:
            out.append(nm)
        inner = getattr(item, "_tools", None) or getattr(item, "tools", None)
        if isinstance(inner, (list, tuple)):
            flat_tool_names(inner, out, depth + 1)
    return out


def compile_preflight():
    from google.adk.code_executors.base_code_executor import BaseCodeExecutor
    cls = type("MockExec", (BaseCodeExecutor,), {n: (lambda self, *a, **k: None) for n in getattr(BaseCodeExecutor, "__abstractmethods__", ())})
    try:
        ex = cls()
    except Exception:
        ex = None

    def run_command(command: str) -> str:
        """Run a shell command."""
        return "ok"

    def read_file(filepath: str, start_line: int = None, end_line: int = None) -> str:
        """Read a file."""
        return "ok"

    def edit_file(filepath: str, old_string: str, new_string: str, allow_multiple: bool = False) -> str:
        """Edit a file."""
        return "ok"

    def write_file(filepath: str, content: str) -> str:
        """Write a file."""
        return "ok"

    def submit_patch() -> str:
        """Submit."""
        return "ok"
    tools = {f.__name__: f for f in (run_command, read_file, edit_file, write_file, submit_patch)}
    limits, gen = build_submission_limits()
    rep = {}
    for arm in ARMS:
        sub = BUNDLE_ROOT / arm["bundle"]
        agent = compile_submission(submission_dir=sub, tool_registry=tools, model_registry=registry_for(sub), code_executor=ex,
                                   script_timeout=240, limits=limits, generation_constraints=gen)
        names = flat_tool_names(getattr(agent, "tools", None))
        gcc = getattr(agent, "generate_content_config", None)
        rep[arm["name"]] = {"tools": names, "seed": getattr(gcc, "seed", None), "temperature": getattr(gcc, "temperature", None)}
    # name discovery walks private ADK attributes, so a miss is logged, not fatal (a compile error IS fatal)
    rep["skill_tools_attached_in_B"] = "run_skill_script" in rep[ARMS[1]["name"]]["tools"]
    rep["skill_tools_absent_in_A"] = "run_skill_script" not in rep[ARMS[0]["name"]]["tools"]
    if not (rep["skill_tools_attached_in_B"] and rep["skill_tools_absent_in_A"]):
        log("WARNING compile preflight: skill tool names not where expected:", json.dumps(rep)[:600])
    return rep


try:
    STATE["preflight"]["compile"] = compile_preflight()
    log("PREFLIGHT compile:", json.dumps(STATE["preflight"]["compile"]))
except Exception as e:
    STATE["status"] = f"aborted: compile preflight failed: {type(e).__name__}: {str(e)[:400]}"
    persist(STATE["status"])
    log("FATAL:", STATE["status"])
    sys.exit(0)

all_tasks = {json.loads(l)["instance_id"]: json.loads(l) for l in open(tasks_path, encoding="utf-8") if l.strip()}
missing = [t for t in CFG["task_ids"] if t not in all_tasks]
if missing:
    log("WARNING task ids not in tasks.jsonl (dropped):", missing)
TASK_IDS = [t for t in CFG["task_ids"] if t in all_tasks]
AB_TASKS = WORK / "ab_tasks.jsonl"  # the arms' task file: only the A/B tasks, in the fixed run order
with open(AB_TASKS, "w", encoding="utf-8") as f:
    for t in TASK_IDS:
        f.write(json.dumps(all_tasks[t]) + "\n")

# ---------------------------------------------------------------- 4. one vLLM server for both arms
ts = time.time()
server.start()
log(f"vLLM up after {time.time() - ts:.0f}s")
if getattr(server, "log_path", None) and os.path.exists(server.log_path):
    for line in open(server.log_path, encoding="utf-8", errors="replace"):
        if any(k in line for k in ("KV cache", "Maximum concurrency")):
            log("VLLM", line.strip()[-200:])

# ---------------------------------------------------------------- 5. both arms at once, with a time guard
import functools, inspect  # noqa: E401,E402
import swegemma.context as _sg_ctx  # noqa: E402
from google.adk.agents.context_cache_config import ContextCacheConfig  # noqa: E402
from google.adk.apps._configs import EventsCompactionConfig  # noqa: E402
from swegemma.evaluate import Evaluator, TaskResult  # noqa: E402

# Team runner fix for concurrency > 1: ADK calls sync tools on the event loop, so one task's long command froze
# every concurrent task. Run each task's tools in a worker thread, one at a time per task.
_sg_create_tools = _sg_ctx.create_context_tools


def _tool_to_thread(fn, lock):
    if not callable(fn) or inspect.iscoroutinefunction(fn):
        return fn

    @functools.wraps(fn)
    async def _threaded(*a, **kw):
        async with lock:
            return await asyncio.to_thread(fn, *a, **kw)
    return _threaded


def _create_tools_threaded(ctx):
    lock = asyncio.Lock()
    return {k: _tool_to_thread(f, lock) for k, f in _sg_create_tools(ctx).items()}


_sg_ctx.create_context_tools = _create_tools_threaded


def res_dict(res):
    return {k: getattr(res, k, None) for k in ("resolved", "agent_patch", "tool_calls", "total_llm_calls", "duration_seconds",
                                               "error", "test_exit_code")}


class ABEvaluator(Evaluator):
    arm_name = "?"

    async def evaluate_task(self, task, *args, **kwargs):
        if time.time() - T0 > SOFT_S:
            STATE["skipped"][self.arm_name].append(task.instance_id)
            return TaskResult(instance_id=task.instance_id, repo=task.repo, resolved=False, agent_patch="", test_output="",
                              test_exit_code=-1, duration_seconds=0.0, error="skipped: time guard",
                              task_index=kwargs.get("task_index", 0))
        t = time.time()
        try:
            res = await super().evaluate_task(task, *args, **kwargs)
        except Exception as e:
            STATE["errors"].append(f"{self.arm_name}/{task.instance_id}: {type(e).__name__}: {str(e)[:200]}")
            ROWS.append(make_row(self.arm_name, task.instance_id, {"error": f"{type(e).__name__}: {e}"}, time.time() - t,
                                 self.config.results_dir))
            persist("running")
            raise
        try:
            ROWS.append(make_row(self.arm_name, task.instance_id, res_dict(res), time.time() - t, self.config.results_dir))
            s = persist("running")
            log(f"TASK_DONE {self.arm_name} {task.instance_id} resolved={res.resolved} calls={res.tool_calls} "
                f"{res.duration_seconds:.0f}s | " + " ".join(f"{a}:{v['resolved']}/{v['n_done']}" for a, v in s["arms"].items()))
        except Exception as e:
            log("ROW_FAILED", task.instance_id, type(e).__name__, str(e)[:300])
        return res


limits, gen = build_submission_limits()


def make_eval(arm):
    sub = BUNDLE_ROOT / arm["bundle"]
    raw = yaml.safe_load((sub / "eval_config.yaml").read_text()) or {}
    ev = {"timeout_seconds": 300, "max_tool_calls": 100, "max_time_minutes": 60, "max_turns": 500}
    ev.update({k: v for k, v in (raw.get("evaluation") or {}).items() if k in ev})
    cfg = EvalConfig(
        tasks_path=AB_TASKS, snapshots_dir=DATA / "snapshots", results_dir=WORK / "results" / arm["name"],
        submission_dir=sub, models=registry_for(sub), sandbox="subprocess",
        timeout_seconds=ev["timeout_seconds"], max_time_minutes=ev["max_time_minutes"],
        max_tool_calls=ev["max_tool_calls"], max_turns=ev["max_turns"], limits=limits, generation_constraints=gen,
        context_cache_config=ContextCacheConfig(min_tokens=2048, ttl_seconds=1800, cache_intervals=10),
        # HARNESS_README 7.2 scorer values; the team runner had compaction_interval=5 (known fix: 15)
        events_compaction_config=EventsCompactionConfig(compaction_interval=int(CFG.get("compaction_interval", 15)), overlap_size=2,
                                                        token_threshold=14336, event_retention_size=5),
        graph_dir=str(DATA / "graphs"), embeddings_dir=str(DATA / "embeddings"), wheels_dir=DATA / "wheels",
        task_ids=TASK_IDS, concurrency=int(CFG["concurrency_per_arm"]), display_mode="quiet", verbose=False)
    e = ABEvaluator(cfg)
    e.arm_name = arm["name"]
    log(f"ARM {arm['name']}: bundle={arm['bundle']} eval={ev} tasks={len(TASK_IDS)} concurrency={CFG['concurrency_per_arm']}")
    return e


async def run_arms():
    evs = [make_eval(a) for a in ARMS]
    remaining = HARD_S - (time.time() - T0)
    log(f"starting both arms; soft deadline in {(SOFT_S - (time.time() - T0)) / 60:.0f} min, hard in {remaining / 60:.0f} min")
    try:
        res = await asyncio.wait_for(asyncio.gather(*(e.run() for e in evs), return_exceptions=True), timeout=max(60, remaining))
        for a, r in zip(ARMS, res):
            if isinstance(r, Exception):
                log(f"ARM_FAILED {a['name']}: {type(r).__name__}: {str(r)[:300]}")
                STATE["errors"].append(f"arm {a['name']}: {type(r).__name__}: {str(r)[:200]}")
        return "done"
    except asyncio.TimeoutError:
        log("HARD DEADLINE reached: in-flight tasks cancelled; partial results kept")
        return "partial (hard deadline)"


STATE["status"] = "running"
persist("running")
try:
    status = asyncio.run(run_arms())
except Exception as e:
    status = f"failed: {type(e).__name__}: {str(e)[:300]}"
    log("RUN_FAILED", status)
if STATE["skipped"] and status == "done":
    status = "partial (time guard)"
# traces are complete now: refresh the trace-derived fields of every row
for i, r in enumerate(ROWS):
    try:
        ROWS[i] = {**make_row(r["arm"], r["task_id"], {"resolved": r["resolved"], "agent_patch": r["patch"], "tool_calls": r["tool_calls"],
                                                       "total_llm_calls": r["llm_calls"], "duration_seconds": r["seconds"],
                                                       "error": r["error"], "test_exit_code": r["test_exit_code"]},
                             r["wall_seconds"], WORK / "results" / r["arm"]), "t_finished_min": r["t_finished_min"]}
    except Exception as e:
        log("REFRESH_FAILED", r.get("task_id"), e)
S = persist(status)
log("SUMMARY", json.dumps({k: S[k] for k in ("status", "elapsed_min", "arms")}))
log("PAIRED", json.dumps(S.get("paired", {})))
# Kaggle's output listing stops at 500 entries (team note), so ship the per-task dirs as one tarball
r = sh(f"cd {WORK}/results && tar -czf {WORK}/ab_results_full.tgz .")
if r.returncode == 0:
    shutil.rmtree(WORK / "results", ignore_errors=True)
try:
    if getattr(server, "log_path", None) and os.path.exists(server.log_path):
        shutil.copy(server.log_path, WORK / "vllm_main.log")
    server.stop()
except Exception as e:
    log("server stop:", e)
log(f"ALL_DONE after {(time.time() - T0) / 3600:.2f} h")
if "ipykernel" not in sys.modules:
    sys.stdout.flush()
    os._exit(0)
